  canvas.addEventListener('pointerdown',ev=>{const p=point(ev);let hit=null,resize=false;const e=selected();if(e&&p.x>=e.x+e.w-13&&p.x<=e.x+e.w+7&&p.y>=e.y+e.h-13&&p.y<=e.y+e.h+7){hit=e;resize=true}else for(let i=state.elements.length-1;i>=0;i--){const it=state.elements[i];if(p.x>=it.x&&p.x<=it.x+it.w&&p.y>=it.y&&p.y<=it.y+it.h){hit=it;break}}if(hit){state.selected=hit.id;pushUndo();state.drag={id:hit.id,resize,sx:p.x,sy:p.y,x:hit.x,y:hit.y,w:hit.w,h:hit.h};canvas.setPointerCapture(ev.pointerId);renderAll();ev.preventDefault()}else{state.selected=null;renderAll()}});
  canvas.addEventListener('pointermove',ev=>{if(!state.drag)return;const p=point(ev),e=state.elements.find(q=>q.id===state.drag.id);if(!e)return;const dx=p.x-state.drag.sx,dy=p.y-state.drag.sy;if(state.drag.resize){e.w=clamp(Math.round(state.drag.w+dx),8,1280);e.h=clamp(Math.round(state.drag.h+dy),8,720)}else{e.x=clamp(Math.round(state.drag.x+dx),-640,1280);e.y=clamp(Math.round(state.drag.y+dy),-360,720)}draw();renderInspector();updateJson()});
  function stopDrag(){if(state.drag){state.drag=null;renderAll()}}canvas.addEventListener('pointerup',stopDrag);canvas.addEventListener('pointercancel',stopDrag);canvas.addEventListener('lostpointercapture',stopDrag);
  function download(name,blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
