  $('#projectBtn').addEventListener('click',()=>{projectName=prompt(localizeRuntime('Project name'),projectName)||projectName;try{const id=localStorage.getItem('ice-ui-active-project')||('p'+Date.now());localStorage.setItem('ice-ui-active-project',id);const all=JSON.parse(localStorage.getItem('ice-ui-projects')||'{}');all[id]={id,name:projectName,updated:Date.now(),data:projectData()};localStorage.setItem('ice-ui-projects',JSON.stringify(all));renderAll();downloadText(cleanName(projectName)+'-bedrock-ui-project.json',JSON.stringify(projectData(),null,2));notice('Project saved','Saved in this browser and downloaded a backup JSON.')}catch{downloadText('bedrock-ui-project.json',JSON.stringify(projectData(),null,2));notice('Backup exported','Browser storage may be full. The project JSON backup was downloaded.')}});
  $('#importBtn').addEventListener('click',()=>$('#projectFile').click());
  $('#projectFile').addEventListener('change',async ev=>{const f=ev.target.files&&ev.target.files[0];ev.target.value='';if(!f)return;try{const data=JSON.parse(await f.text());if(!data||!Array.isArray(data.elements))throw Error('format');pushUndo();state.elements=data.elements.map(e=>({...e}));state.nextId=Math.max(1,...state.elements.map(e=>parseInt(String(e.id).replace(/\D/g,''),10)||0))+1;state.selected=state.elements[0]?.id||null;projectName=data.name||'Imported project';jsonFiles={...jsonFiles,...(data.jsonFiles||{})};storageFiles={...(data.storageFiles||{})};storageFolders=[...new Set([...storageFolders,...(data.storageFolders||[])])];for(const [key,meta] of Object.entries(data.assets||{})){if(meta.data){assetData[key]=meta;const im=new Image();im.src=meta.data;await new Promise((res,rej)=>{im.onload=res;im.onerror=rej});files[key]=im}}renderAll();showEditor();localStorage.setItem('ice-ui-open-editor','1');notice('Project opened','Layout and saved assets loaded.')}catch{notice('Could not open file','Choose a project JSON file created by Bedrock UI Studio.')}});
  function dataUrlBytes(url){const b64=url.split(',')[1]||'';const raw=atob(b64);const out=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)out[i]=raw.charCodeAt(i);return out}
  function crc32(bytes){let c=~0;for(let i=0;i<bytes.length;i++){c^=bytes[i];for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xEDB88320:0)}return (~c)>>>0}
  function makeZip(entries){const enc=new TextEncoder();const filesOut=[];const central=[];let offset=0;const u16=n=>[n&255,(n>>>8)&255];const u32=n=>[n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255];for(const entry of entries){const name=enc.encode(entry.name);const data=entry.bytes instanceof Uint8Array?entry.bytes:enc.encode(entry.text||'');const crc=crc32(data);const local=new Uint8Array([...u32(0x04034b50),...u16(20),...u16(0x0800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...name,...data]);filesOut.push(local);const cd=new Uint8Array([...u32(0x02014b50),...u16(20),...u16(20),...u16(0x0800),...u16(0),...u16(0),...u16(0),...u32(crc),...u32(data.length),...u32(data.length),...u16(name.length),...u16(0),...u16(0),...u16(0),...u16(0),...u32(0),...u32(offset),...name]);central.push(cd);offset+=local.length}const centralLength=central.reduce((n,a)=>n+a.length,0);const eocd=new Uint8Array([...u32(0x06054b50),...u16(0),...u16(0),...u16(entries.length),...u16(entries.length),...u32(centralLength),...u32(offset),...u16(0)]);return new Blob([...filesOut,...central,eocd],{type:'application/zip'})}
  function colorPixel(hex,alpha){const h=(hex||'#102a40').replace('#','');const v=parseInt(h.length===3?h.split('').map(c=>c+c).join(''):h,16);return [(v>>16)&255,(v>>8)&255,v&255,Math.round(255*alpha/100)]}
  function makeTexture(e,variant='base') {const dpr=2,w=Math.max(16,Math.min(1200,Math.round(e.w*dpr))),h=Math.max(16,Math.min(900,Math.round(e.h*dpr)));const c=document.createElement('canvas');c.width=w;c.height=h;const g=c.getContext('2d');let [r,gg,b,a]=colorPixel(variant==='hover'?(e.hoverBg||'#25b7c7'):variant==='pressed'?(e.pressedBg||'#075b78'):(e.bg||'#102a40'),e.alpha??100);g.clearRect(0,0,w,h);const radius=Math.min((e.radius||0)*dpr,w/2,h/2);g.beginPath();g.moveTo(radius,0);g.arcTo(w,0,w,h,radius);g.arcTo(w,h,0,h,radius);g.arcTo(0,h,0,0,radius);g.arcTo(0,0,w,0,radius);g.closePath();g.fillStyle=`rgba(${r},${gg},${b},${a/255})`;g.fill();g.lineWidth=Math.max(1,2*dpr);g.strokeStyle='rgba(89,228,255,.85)';g.stroke();return c.toDataURL('image/png')}
  async function exportZip(){
    if(!state.elements.length){notice('No elements yet','Add an element to the canvas first.');return}
    const rp=[];const bp=[];const native=toNativeJson().json;const uuid=()=> 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g,c=>{const r=Math.random()*16|0;return (c==='x'?r:(r&3|8)).toString(16)});
    const rpManifest=makeManifest('resources',projectName+' Resource Pack');const bpManifest=makeManifest('data',projectName+' Behavior Pack');
    for(const e of state.elements){const k=cleanName(e.id);if(e.type==='image'&&e.asset&&assetData[e.asset]?.data){const path='textures/ui/'+cleanName(e.id+'_'+(e.assetName||'image').replace(/\.[^.]+$/,''))+'.png';rp.push({name:path,bytes:dataUrlBytes(assetData[e.asset].data)});const control=native.ice_ui_root.controls.find(o=>o[k]);if(control&&control[k])control[k].texture=path.replace(/\.png$/,'')}else if((e.type==='panel'||e.type==='button')&&e.textureMode==='custom'&&(e.textureAsset&&assetData[e.textureAsset]?.data||Object.values(e.stateTextures||{}).some(key=>key&&assetData[key]?.data))){const keys=[e.textureAsset,...Object.values(e.stateTextures||{})].filter(Boolean);for(const key of keys){const meta=assetData[key];if(!meta?.data)continue;const base='textures/ui/'+cleanName(meta.name.replace(/\.[^.]+$/,''));if(!rp.some(x=>x.name===base+'.png'))rp.push({name:base+'.png',bytes:dataUrlBytes(meta.data)})}if(e.type==='button'&&!e.textureAsset){for(const [variant,suffix] of [['default','default'],['hover','hover'],['pressed','pressed']]){if(e.stateTextures?.[variant]&&assetData[e.stateTextures[variant]]?.data)continue;rp.push({name:'textures/ui/'+k+'_'+suffix+'.png',bytes:dataUrlBytes(makeTexture(e,variant==='default'?'base':variant))})}}}else if(e.type==='panel'&&e.textureMode!=='vanilla'){const base='textures/ui/'+k+'_background';rp.push({name:base+'.png',bytes:dataUrlBytes(makeTexture(e))});const c=native.ice_ui_root.controls.find(o=>o[k]);if(c&&c[k])c[k].texture=base}else if(e.type==='button'&&e.textureMode!=='vanilla'){for(const [variant,suffix] of [['base','default'],['hover','hover'],['pressed','pressed']])rp.push({name:'textures/ui/'+k+'_'+suffix+'.png',bytes:dataUrlBytes(makeTexture(e,variant))})}}
    rp.push({name:'manifest.json',text:storageFiles['resource_pack/manifest.json']?.text||JSON.stringify(rpManifest,null,2)},{name:'ui/_ui_defs.json',text:JSON.stringify({ui_defs:['ui/ui_studio_layout.json']},null,2)},{name:'ui/ui_studio_layout.json',text:JSON.stringify(native,null,2)},{name:'bedrock-ui-project.json',text:JSON.stringify(projectData(),null,2)});
    for(const [path,content] of Object.entries(jsonFiles)){if(path!=='ui/ui_studio_layout.json'&&path!=='ui/_ui_defs.json'&&path!=='manifest.json')rp.push({name:path.replace(/^resource_pack\//,''),text:content})}
    for(const [path,f] of Object.entries(storageFiles)){if(path==='resource_pack/manifest.json')continue;const target=path.startsWith('behavior_pack/')?'bp':path.startsWith('resource_pack/')?'rp':(path.startsWith('scripts/')?'bp':'rp');const rel=path.replace(/^(behavior_pack|resource_pack)\//,'');const entry=f.kind==='png'?{name:rel,bytes:dataUrlBytes(f.data)}:{name:rel,text:f.text||''};(target==='bp'?bp:rp).push(entry)}
    if(!bp.some(x=>x.name==='manifest.json'))bp.push({name:'manifest.json',text:JSON.stringify(bpManifest,null,2)});else{const m=bp.find(x=>x.name==='manifest.json');try{const parsed=JSON.parse(m.text);if(!parsed.modules?.some(x=>x.type==='script')){parsed.modules=parsed.modules||[];parsed.modules.push({type:'script',language:'javascript',uuid:uuid(),version:[1,0,0],entry:'scripts/main.js'});parsed.dependencies=[{module_name:'@minecraft/server',version:'2.9.0'},{module_name:'@minecraft/server-ui',version:'2.0.0'}];m.text=JSON.stringify(parsed,null,2)}}catch{}}
    if(!bp.some(x=>x.name==='scripts/main.js'))bp.push({name:'scripts/main.js',text:`import { ActionFormData, MessageFormData, ModalFormData } from '@minecraft/server-ui';\nimport { world } from '@minecraft/server';\n\n// Example server form. Call openMainMenu(player) from your own item/event trigger.\nexport function openMainMenu(player) {\n  const form = new ActionFormData()\n    .title('Server Menu')\n    .body('Choose an option')\n    .button('Profile')\n    .button('Teleport')\n    .button('Settings');\n  form.show(player).then(result => {\n    if (result.canceled) return;\n    if (result.selection === 0) new MessageFormData().title('Profile').body('Add your player data here.').button1('OK').button2('Close').show(player);\n    if (result.selection === 1) new ActionFormData().title('Teleport').body('Choose a destination').button('Spawn').button('Random').show(player);\n    if (result.selection === 2) new ModalFormData().title('Settings').toggle('Example setting', true).show(player);\n  }).catch(() => {});\n}\n\n// Demo trigger: use a stick to open the form.\nworld.afterEvents.itemUse.subscribe(event => {\n  if (event.itemStack?.typeId === 'minecraft:stick') openMainMenu(event.source);\n});\n`});
    rp.push({name:'README.txt',text:'BEDROCK UI STUDIO — ADDON STARTER\n\nThis .mcaddon contains a Resource Pack and a Behavior Pack with generated manifests. The RP contains the reusable JSON UI layout and textures. The BP includes an example @minecraft/server-ui form script.\n\nImportant: Server forms (ActionFormData, MessageFormData, ModalFormData) are built in JavaScript, not defined as standalone JSON forms. Chest/container UI is a Resource Pack JSON UI customization of existing vanilla screens, such as chest_screen.json, and must be integrated carefully with the vanilla screen structure. Registering a JSON file in _ui_defs.json alone does not guarantee a visible new screen.\n\nButton default/hover/pressed visuals are generated for the preview elements. Custom UI JSON needs version-specific testing; this starter is not guaranteed to replace the vanilla chest screen automatically.\n'});
    const outer=[{name:cleanName(projectName)+'_RP.mcpack',bytes:new Uint8Array(await makeZip(rp).arrayBuffer())},{name:cleanName(projectName)+'_BP.mcpack',bytes:new Uint8Array(await makeZip(bp).arrayBuffer())},{name:'bedrock-ui-project.json',text:JSON.stringify(projectData(),null,2)}];download(cleanName(projectName)+'.mcaddon',makeZip(outer));notice('Addon exported','The .mcaddon contains BP + RP manifests, your storage files, UI JSON, textures, and an example server-form script. Test the packs in Minecraft and review README.txt.');
  }
